patch:
diff --git a/scripts/level-compiler.mjs b/scripts/level-compiler.mjs
index 49a2f8b..23ab093 100644
--- a/scripts/level-compiler.mjs
+++ b/scripts/level-compiler.mjs
@@ -805,6 +805,11 @@ function compileSectors(source, context, warnings) {
       const mirror = requireBoolean(context, waveWhere, "mirror", wave.mirror, false);
       const onCleared = requireBoolean(context, waveWhere, "afterCleared",
         wave.afterCleared, false);
+      const fireMode = wave.fire ?? "normal";
+      const fireBits = {normal:0, volley:0x40, column:0x80, "volley-column":0xc0}[fireMode];
+      if (fireBits === undefined) fail(context,waveWhere,"fire must be normal, volley, column or volley-column");
+      if (wave.fire !== undefined && wave.path === undefined)
+        fail(context,waveWhere,"fire envelopes require a free Light path wave");
       if (wave.path !== undefined) {
         if(waveClass!=="light" || !isSpace)
           fail(context,waveWhere,"a path requires a free Light wave in SPACE");
@@ -852,10 +857,10 @@ function compileSectors(source, context, warnings) {
       }
       // wave_flags: bits 0-1 appearance slot, bit 2 mirror, bit 3 Heavy class,
       // bit 4 after-cleared, bit 5 armoured Raider,
-      // bits 6-7 the Interceptor's loops.
+      // bits6-7: path-Light fire modes, otherwise Interceptor loops (Q4A).
       const flags = appearance | (mirror ? 0x04 : 0) |
         (waveClass === "heavy" ? 0x08 : 0) | (onCleared ? 0x10 : 0) |
-        (heavyKind === "armoured" ? 0x20 : 0) | loops << 6;
+        (heavyKind === "armoured" ? 0x20 : 0) | (wave.path !== undefined ? fireBits : loops << 6);
       waves.push({
         sector: index + 1, row, flags, count, spacing, entry, appearance, mirror,
         onCleared, loops, archetype, escort, class: waveClass, kind: heavyKind, motion, path:wave.path, hold: wave.hold ?? null,
diff --git a/src/c/lifecycle.c b/src/c/lifecycle.c
index f52f7be..dba7419 100644
--- a/src/c/lifecycle.c
+++ b/src/c/lifecycle.c
@@ -1898,7 +1898,7 @@ void enemy_c_heavy_look_colour(void)
 #pragma code-name (pop)
 #pragma code-name (pop)

-/* M3 checkpoints 1-2: phase-exclusive path state and C movement/fire policy.
+/* M3 checkpoints 1-3: phase-exclusive path state and C movement/fire policy.
  * $FF is resident-archetype fallback, not a kernel action. No C stack args. */
 #pragma data-name (push, "CONTENT_DATA")
 uint8_t m3_path_segment[4] = {255u,255u,255u,255u};
@@ -1908,9 +1908,12 @@ static uint8_t m3_index = 0u;
 static uint8_t m3_flags = 0u;
 static uint8_t m3_dy = 0u;
 static uint8_t m3_mirror_phase = 0u;
+static uint8_t m3_pulse_frame = 255u;
+static uint8_t m3_pulse_mask = 0u;
 #pragma data-name (pop)
 #pragma rodata-name (push, "CONTENT_DATA")
 static const uint8_t m3_next_step[4] = {3u,253u,250u,247u};
+static const uint8_t m3_slot_bit[4] = {1u,2u,4u,8u};
 #pragma rodata-name (pop)
 #pragma code-name (push, "CONTENT_CODE")
 void m3_reset(void)
@@ -1923,6 +1926,8 @@ void m3_reset(void)
     } while (m3_index != 0u);
     m3_armed_path = M3_NO_PATH;
     m3_mirror_phase = 0u;
+    m3_pulse_frame = 255u;
+    m3_pulse_mask = 0u;
 }

 void m3_wave_arm(void)
@@ -1937,6 +1942,7 @@ void m3_escort(void)
 {
     m3_path_segment[light_slot] = M3_NO_PATH;
     m3_path_timer[light_slot] = 0u;
+    m3_pulse_mask &= (uint8_t)~m3_slot_bit[light_slot];
 }

 void m3_admit(void)
@@ -1953,11 +1959,49 @@ void m3_admit(void)
     }
 }

+static uint8_t m3_column_ok(void)
+{
+    light_target_x = (uint8_t)((uint8_t)(PLAYER_X + 6u) & 0xFCu);
+    return (uint8_t)(light_x[light_slot] - light_target_x + 4u) < 9u;
+}
+
+/* One snapshot before the first volley member moves on a 64-frame opening.
+ * Other members cannot join late, even if an admission reuses a masked slot.
+ * A denied token leaves reloads ready for a later opening, with no backlog.
+ * Each member rechecks its post-motion fire/column bounds before emission. */
+static void m3_prepare_volley(void)
+{
+    if ((FRAME_COUNTER & 63u) != 0u || m3_pulse_frame == FRAME_COUNTER) return;
+    m3_pulse_frame = FRAME_COUNTER;
+    m3_pulse_mask = 0u;
+    if ((PLAYER_LIFECYCLE & 1u) != 0u) return;
+    light_slot_save = light_slot;
+    light_slot = LIGHT_SLOT_COUNT;
+    do {
+        --light_slot;
+        if (light_state[light_slot] == LIGHT_ACTIVE_FREE &&
+            m3_path_segment[light_slot] != M3_NO_PATH &&
+            (light_loops[light_slot] & 64u) != 0u &&
+            light_fire_timer[light_slot] == 0u &&
+            light_y[light_slot] >= LIGHT_FIRE_TOP &&
+            light_y[light_slot] < LIGHT_FIRE_BOTTOM) {
+            m3_index = (uint8_t)((m3_path_segment[light_slot] & 127u) + 2u);
+            if ((level_paths[m3_index] & 16u) != 0u &&
+                ((light_loops[light_slot] & 128u) == 0u || m3_column_ok() != 0u)) {
+                m3_pulse_mask |= m3_slot_bit[light_slot];
+            }
+        }
+    } while (light_slot != 0u);
+    light_slot = light_slot_save;
+    if (m3_pulse_mask != 0u && light_take_token() == 0u) m3_pulse_mask = 0u;
+}
+
 uint8_t m3_path_tick(void)
 {
     m3_index = m3_path_segment[light_slot];
     if (m3_index == M3_NO_PATH) return M3_NO_PATH;
-    m3_index &= 127u;
+    if ((light_loops[light_slot] & 64u) != 0u) m3_prepare_volley();
+    m3_index = m3_path_segment[light_slot] & 127u;
     m3_dy = level_paths[m3_index];
     ++m3_index;
     ++m3_index;
@@ -2023,7 +2067,12 @@ uint8_t m3_path_tick(void)
     }
     if ((m3_flags & 16u) == 0u || light_work < LIGHT_FIRE_TOP ||
         light_work >= LIGHT_FIRE_BOTTOM || (PLAYER_LIFECYCLE & 1u) != 0u) return 0u;
-    if (light_take_token() == 0u) return 0u;
+    if ((light_loops[light_slot] & 128u) != 0u && m3_column_ok() == 0u) return 0u;
+    if ((light_loops[light_slot] & 64u) != 0u) {
+        if ((FRAME_COUNTER & 63u) != 0u ||
+            (m3_pulse_mask & m3_slot_bit[light_slot]) == 0u) return 0u;
+        m3_pulse_mask ^= m3_slot_bit[light_slot];
+    } else if (light_take_token() == 0u) return 0u;
     light_reload();
     return LIGHT_FIELD(ENEMY_ARCHETYPE_FIELD_WEAPON);
 }
